import{_ as d,o as e,c as o,al as c}from"./chunks/framework.Bm7de0lE.js";const u=JSON.parse('{"title":"版本与兼容性政策","description":"","frontmatter":{},"headers":[],"relativePath":"guide/versioning.md","filePath":"guide/versioning.md","lastUpdated":1786462308000}'),a={name:"guide/versioning.md"};function r(n,t,s,i,h,l){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="版本与兼容性政策" tabindex="-1">版本与兼容性政策 <a class="header-anchor" href="#版本与兼容性政策" aria-label="Permalink to &quot;版本与兼容性政策&quot;">​</a></h1><p>这一页回答一个问题：<strong>升级到下一个 <code>1.x</code> 小版本，我依赖的东西会不会变。</strong></p><p>XiHan.UI 的公开面横跨五种介质，因为「丢掉自带皮肤自己写一套」「手写 Light DOM 结构」都是被 <a href="./styling">皮肤与样式分层</a> 和 <a href="./anatomy">解剖与部件契约</a> 公开教过的用法：</p><table tabindex="0"><thead><tr><th>介质</th><th>使用者写在哪里</th><th>例子</th></tr></thead><tbody><tr><td>JS / TS 导出</td><td>自己的源码</td><td><code>import { XhSelectRoot } from &#39;@xihan-ui/vue&#39;</code></td></tr><tr><td>解剖属性</td><td>CSS 选择器</td><td><code>[data-scope=&#39;select&#39;][data-part=&#39;trigger&#39;]</code></td></tr><tr><td><code>data-*</code> 状态属性</td><td>CSS 选择器</td><td><code>[data-state=&#39;open&#39;]</code>、<code>[data-tone=&#39;danger&#39;]</code></td></tr><tr><td>CSS 自定义属性与 <code>@layer</code> 名</td><td>自己的样式表</td><td><code>--xh-bg-brand</code>、<code>@layer xihan.overrides</code></td></tr><tr><td>自定义元素标签与 attribute</td><td>自己的 HTML</td><td><code>&lt;xh-dialog modal=&quot;true&quot;&gt;</code>、<code>data-xh-part=&quot;content&quot;</code></td></tr></tbody></table><p>破坏其中任何一种，都不会有编译错误、不会有运行时异常、也不会有降级——只会是「样式没了」或「按钮不响应」。所以这一页对五种介质<strong>逐类</strong>给出结论，不留空白。</p><div class="warning custom-block"><p class="custom-block-title">1.0.0 之前不适用</p><p><code>1.0.0-alpha.*</code> / <code>1.0.0-beta.*</code> 阶段的任何改动都不受本页约束，包括删除导出、改属性名、收窄类型。本页的全部条款从 <code>1.0.0</code> 正式版那一刻起生效。</p></div><h2 id="三个档位" tabindex="-1">三个档位 <a class="header-anchor" href="#三个档位" aria-label="Permalink to &quot;三个档位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>档位</th><th>含义</th></tr></thead><tbody><tr><td><strong>受约束</strong></td><td>改名、删除、收窄语义 = major。新增同类成员 = minor。</td></tr><tr><td><strong>只增不减</strong></td><td>只保证「已经有的不会消失、不会改名」。往里加字段、加条目不算破坏。</td></tr><tr><td><strong>排除</strong></td><td>明确不在承诺内，任何版本都可能改。使用者不应依赖。</td></tr></tbody></table><p>版本号本身走标准语义化版本：<code>major.minor.patch</code>。受约束的东西改了走 major，新增走 minor，只修行为不改名字走 patch。</p><h2 id="_14-个包必须同版本安装" tabindex="-1">14 个包必须同版本安装 <a class="header-anchor" href="#_14-个包必须同版本安装" aria-label="Permalink to &quot;14 个包必须同版本安装&quot;">​</a></h2><p>14 个包锁步发布：任何一个包发新版本，全部 14 个包一起发同一个号。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@xihan-ui/kernel   @xihan-ui/machine        @xihan-ui/behavior</span></span>\n<span class="line"><span>@xihan-ui/position @xihan-ui/tokens         @xihan-ui/styles</span></span>\n<span class="line"><span>@xihan-ui/headless @xihan-ui/icons          @xihan-ui/vue</span></span>\n<span class="line"><span>@xihan-ui/web-components  @xihan-ui/chat-stream</span></span>\n<span class="line"><span>@xihan-ui/markdown @xihan-ui/code-highlight @xihan-ui/backgrounds</span></span></code></pre></div><p>两条后果，都要知道：</p><ul><li><strong>某个包的 major 可能不含任何针对它自己的变更。</strong> <code>@xihan-ui/markdown</code> 升到 <code>2.0.0</code> 完全可能只是因为 <code>@xihan-ui/vue</code> 改了一个 prop。判断某次 major 影响到你没有，看 <a href="./../changelog">更新日志</a> 的分类条目，不要看版本号跨度。</li><li><strong>不要混装版本。</strong> <code>@xihan-ui/vue</code> 与 <code>@xihan-ui/headless</code> 版本不一致时，类型会对不上；<code>@xihan-ui/web-components</code> 更硬——同一个 <code>xh-</code> 标签被两个版本注册会直接抛错，整页挂掉。适配器与它的兄弟包目前是普通 <code>dependencies</code>，包管理器不会阻止你装出这种组合，所以这一条靠你自己保证（见<a href="#仍然只靠自觉的">仍然只靠自觉的</a>）。</li></ul><hr><h2 id="一、js-ts-导出面" tabindex="-1">一、JS / TS 导出面 <a class="header-anchor" href="#一、js-ts-导出面" aria-label="Permalink to &quot;一、JS / TS 导出面&quot;">​</a></h2><p>14 个包中 13 个出 JS，共 19 个带类型的入口。</p><h3 id="受约束" tabindex="-1">受约束 <a class="header-anchor" href="#受约束" aria-label="Permalink to &quot;受约束&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>说明</th></tr></thead><tbody><tr><td>包名</td><td>14</td><td>把代码从一个包挪到另一个包 = major</td></tr><tr><td><code>exports</code> 子路径</td><td>19 个 JS 入口</td><td>如 <code>@xihan-ui/vue/backgrounds</code>、<code>@xihan-ui/web-components/define</code>。没有 <code>./*</code> 通配，深路径引用（<code>.../dist/xxx.js</code>）被 Node 与打包器一并挡住，那些路径不是 API</td></tr><tr><td>Vue 组件导出 <code>Xh*</code></td><td>568（102 个家族）</td><td><code>XhButton</code>、<code>XhSelectRoot</code>、<code>XhSelectItemIndicator</code></td></tr><tr><td>Vue 组合式函数 <code>use&lt;家族&gt;</code></td><td>72</td><td><code>useSelect</code>、<code>useCombobox</code>。这是「不用我的部件、自己写标记」的唯一入口</td></tr><tr><td>Vue 指令</td><td>1</td><td><code>vBackground</code>（在 <code>@xihan-ui/vue/backgrounds</code> 子入口，依赖可选 peer）</td></tr><tr><td>无头内核 <code>connect*</code></td><td>102</td><td><code>connectAccordion</code> 及其参数顺序、返回的 getter 名</td></tr><tr><td>无头内核 <code>*Machine</code></td><td>68</td><td>机器 schema 的形状</td></tr><tr><td>类型 <code>*Props</code> / <code>*Api</code> / <code>*ChangeDetails</code> / <code>*Schema</code></td><td>106 / 103 / 106 / 68</td><td>删字段、改字段名、把可选改必填都是 major</td></tr><tr><td>Vue prop 名与「没传」语义</td><td>255 个不同名字 / 958 处声明</td><td>见下方专条</td></tr><tr><td>Vue emit 名集合</td><td>67 个不同名字 / 192 处</td><td>名字本身受约束（列在 <code>emits</code> 里的事件不走 <code>$attrs</code> 透传，删名字会静默改变行为）</td></tr><tr><td>Vue 插槽名</td><td>7</td><td><code>default</code>、<code>item</code>、<code>label</code>、<code>trigger</code>、<code>panel</code>、<code>content</code>、<code>empty</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Vue prop 的「没传」也是契约</p><p><code>disabled</code> 写成裸 <code>Boolean</code>（不传恒为 <code>false</code>）还是 <code>{ type: Boolean, default: undefined }</code>（不传交给底层机器决定），在类型上几乎看不出差别，但决定了你不写这个 prop 时组件怎么表现。仓库里 157 处裸 <code>Boolean</code>、108 处三态、8 处 <code>default: true</code>、1 处显式 <code>default: false</code>。<strong>把某个 prop 从一种改成另一种是 major</strong>，即使名字和类型都没动。</p></div><h3 id="只增不减" tabindex="-1">只增不减 <a class="header-anchor" href="#只增不减" aria-label="Permalink to &quot;只增不减&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>说明</th></tr></thead><tbody><tr><td>Vue 上下文类型 <code>*Context</code> / <code>*Callbacks</code></td><td>92</td><td>用于给透传的 <code>api</code> 标注类型。<strong>只保证可读，不保证可构造</strong>——往里加可选字段不算破坏，所以别写 <code>const c: SelectContext = { … }</code> 这种字面量赋值</td></tr><tr><td><code>custom-elements.json</code>（CEM）</td><td>1 份 / 102 个元素</td><td>已经进过清单的 <code>tagName</code> / <code>attribute</code> / <code>event</code> 条目不会消失；字段完备性与结构细节不承诺（今天 <code>events</code> 没有 <code>type</code>、<code>cssProperties</code> 是空的，后续会补，补充算 minor）</td></tr></tbody></table><h3 id="排除" tabindex="-1">排除 <a class="header-anchor" href="#排除" aria-label="Permalink to &quot;排除&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>为什么排除是安全的</th></tr></thead><tbody><tr><td><code>@xihan-ui/headless</code> 的内部算子与常量</td><td>423</td><td><code>clampRating</code>、<code>buildMonthGrid</code>、<code>colorPickerHexToRgba</code>、<code>CAROUSEL_AUTOPLAY_INTERVAL</code> 这类。它们是内核实现的一部分，改一次实现就得改一次签名。你需要的默认值应当从组件 props 的文档默认值读，不要 import 一个常量再自己比对</td></tr><tr><td><code>@xihan-ui/headless</code> 的内部伴生类型</td><td>163</td><td><code>*Refs</code>（机器持有的 DOM 引用袋）、<code>ColorPickerHsva</code>、<code>CascaderLevel</code> 等，是上面那批函数的参数与返回类型</td></tr><tr><td><code>xxxAnatomy</code> / <code>xxxMeta</code> / <code>xxxKeyboard</code> 三组导出对象</td><td>各 102</td><td><strong>它们描述的 part 名单是受约束的（见第二节），但这三个对象本身的组织方式不是。</strong> 想拿到部件名单，请以组件文档页的解剖表为准，不要 import 这些对象</td></tr><tr><td>Vue 的 <code>provide*</code> / <code>use*Context</code> 函数</td><td>51</td><td><a href="./../adapters/vue">Vue 适配器</a> 早已写明「父子组件之间的 provide / inject 是内部实现，不对外开放」。要下探请用 <code>use&lt;家族&gt;()</code></td></tr><tr><td>Vue 的 <code>useTimelineItem</code></td><td>1</td><td>名字看着像组合式函数，实际是 inject 管道，与上一行同类</td></tr><tr><td>适配器运行时底座</td><td>Vue 3 个、WC 8 个</td><td><code>createVueRuntime</code> / <code>createVueIdGenerator</code> / <code>vueNormalize</code>；<code>createLitRuntime</code> / <code>createSpreader</code> / <code>defineElement</code> / <code>discoverParts</code> / <code>wcNormalize</code> / <code>MachineController</code> 等。这些是适配器与内核之间的接缝，签名依赖的类型没有从同一个包导出，实际也写不出调用</td></tr><tr><td>WC 的元素类导出 <code>Xh*Element</code></td><td>70</td><td>只作 <code>instanceof</code> 与手动 <code>customElements.define</code> 的便利品，<strong>不支持 <code>extends</code></strong>（基类不导出、<code>wire()</code> 是 protected abstract）。要拿元素请用 <code>document.querySelector</code></td></tr><tr><td>WC 元素上的 <code>static partContract</code></td><td>102</td><td>部件校验的输入数据，实现细节</td></tr><tr><td><code>dist/</code> 内部文件名</td><td>—</td><td><code>element-Bx4xCiT2.js</code> 这类打包 chunk 每次构建都可能变，永远不要 deep import</td></tr><tr><td><code>.d.ts</code> 的文件布局</td><td>—</td><td>类型从包入口拿，不要引具体 <code>.d.ts</code> 路径</td></tr><tr><td><code>ui/tooling/</code>、<code>ui/apps/playground-*</code></td><td>—</td><td>不发布</td></tr></tbody></table><hr><h2 id="二、解剖属性-data-scope-data-part" tabindex="-1">二、解剖属性（<code>data-scope</code> / <code>data-part</code>） <a class="header-anchor" href="#二、解剖属性-data-scope-data-part" aria-label="Permalink to &quot;二、解剖属性（`data-scope` / `data-part`）&quot;">​</a></h2><p>这是换皮肤时最核心的一组名字，也是 WC 使用者手写 HTML 时要打的字符串。</p><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>档位</th></tr></thead><tbody><tr><td><code>data-scope</code> 取值（组件身份）</td><td>102</td><td><strong>受约束</strong>（新增第 103 个组件是 minor）</td></tr><tr><td><code>data-part</code> 取值（部件名）</td><td>154 个不同名字 / 569 条「组件 × 部件」配对</td><td><strong>受约束</strong></td></tr><tr><td><code>data-xh-part</code>（WC 作者书写的角色声明）</td><td>属性名 1 个，取值即上面 154 个</td><td><strong>受约束</strong></td></tr><tr><td><code>meta.requiredParts</code>（必备部件）</td><td>213 条</td><td><strong>只增不减</strong>，方向见下</td></tr></tbody></table><p><code>data-scope</code> 的取值与三处完全同名，不做任何转换：headless 目录名、自定义元素标签 <code>xh-&lt;scope&gt;</code>、皮肤文件 <code>&lt;scope&gt;.css</code>。改一个就是四处同时破坏。</p><div class="warning custom-block"><p class="custom-block-title"><code>data-xh-part</code> 是 <code>data-xh-</code> 前缀里唯一的例外</p><p>其余 <code>data-xh-*</code> 属性（<code>data-xh-layer</code>、<code>data-xh-focus-guard</code>、<code>data-xh-scroll-shard</code> 等 8 个）是库自用标记，<strong>排除</strong>在承诺之外。但 <code>data-xh-part</code> 不是——它是 Web Components 适配器唯一的作者输入 API：你写 <code>data-xh-part=&quot;trigger&quot;</code> 是<strong>声明</strong>，元素接线后往同一节点打上 <code>data-scope</code> + <code>data-part</code> 是<strong>事实</strong>。皮肤匹配后者，你永远不该手写后者。</p></div><h3 id="requiredparts-的方向是反的" tabindex="-1">requiredParts 的方向是反的 <a class="header-anchor" href="#requiredparts-的方向是反的" aria-label="Permalink to &quot;requiredParts 的方向是反的&quot;">​</a></h3><p>往 <code>requiredParts</code> 里<strong>加</strong>一条是收紧：昨天能跑的 Light DOM，今天开始在 <a href="./diagnostics">诊断通道</a> 报 <code>wc.missing-part</code>。规则：</p><ul><li>删条目：任何版本都可以。</li><li>加条目：允许在 minor 里做，但新加的必备部件在整整一个 major 周期内只以 <code>warn</code> 级别报出，到下一个 major 才升 <code>error</code>。</li></ul><hr><h2 id="三、data-状态属性" tabindex="-1">三、<code>data-*</code> 状态属性 <a class="header-anchor" href="#三、data-状态属性" aria-label="Permalink to &quot;三、`data-*` 状态属性&quot;">​</a></h2><p><code>connect</code> 一共产出 119 个不同的 <code>data-*</code> 属性名、554 条「组件 × 属性」配对。分两类。</p><h3 id="受约束-1" tabindex="-1">受约束 <a class="header-anchor" href="#受约束-1" aria-label="Permalink to &quot;受约束&quot;">​</a></h3><p><strong>行为契约</strong>——这些不是样式钩子，删掉会让功能静默失效：</p><table tabindex="0"><thead><tr><th>属性</th><th>作用</th></tr></thead><tbody><tr><td><code>data-value</code></td><td>集合型组件的条目值。行为层按它反查节点做方向键导航，WC 使用者要手写在 <code>item</code> 节点上。删掉它，所有集合型组件的键盘导航静默失效</td></tr><tr><td><code>data-name</code></td><td>表单字段名（<code>form</code>）</td></tr><tr><td><code>data-index</code></td><td>条目序号（0 基）</td></tr></tbody></table><p><strong>样式钩子</strong>——自带皮肤自己就消费了 78 个属性名 / 471 条配对，第三方皮肤照着抄的就是这一组：</p><table tabindex="0"><thead><tr><th>属性</th><th>覆盖组件数</th></tr></thead><tbody><tr><td><code>data-state</code></td><td>55</td></tr><tr><td><code>data-size</code></td><td>57</td></tr><tr><td><code>data-disabled</code></td><td>53</td></tr><tr><td><code>data-tone</code></td><td>44</td></tr><tr><td><code>data-placement</code></td><td>22（浮层族）</td></tr><tr><td><code>data-invalid</code></td><td>18</td></tr><tr><td><code>data-highlighted</code></td><td>15</td></tr><tr><td><code>data-orientation</code> / <code>data-side</code> / <code>data-align</code> / <code>data-selected</code> / <code>data-checked</code> / <code>data-readonly</code> …</td><td>其余</td></tr><tr><td><code>data-cols-sm</code> / <code>-md</code> / <code>-lg</code> / <code>-xl</code></td><td>仅 <code>grid</code>，断点分档名受约束</td></tr></tbody></table><p><strong>取值也受约束。</strong> 属性名改了会打碎皮肤，取值改了同样打碎、而且更隐蔽——<code>[data-state=&#39;open&#39;]</code> 在取值改成 <code>expanded</code> 之后仍然是合法 CSS，只是永远不匹配。自带皮肤当前用到的 22 个 <code>data-state</code> 取值全部受约束：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>open  closed  checked  unchecked  indeterminate  some  all  on  none</span></span>\n<span class="line"><span>active  current  visible  ready  empty  invalid  error  collapsed</span></span>\n<span class="line"><span>completed  finishing  dismissing  picking  copying</span></span></code></pre></div><p>三条视觉轴的取值同理。<code>data-tone</code> 的合法值是 6 个，唯一真源是 <code>tone.css</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brand  neutral  success  warning  danger  info</span></span></code></pre></div><h3 id="排除-1" tabindex="-1">排除 <a class="header-anchor" href="#排除-1" aria-label="Permalink to &quot;排除&quot;">​</a></h3><p>其余 38 个 <code>data-*</code>（<code>data-lane</code>、<code>data-one-way</code>、<code>data-checked-count</code>、<code>data-sider-collapsed</code>、<code>data-file-size</code>、<code>data-modules</code> 等）——自带皮肤没有选中它们、组件文档页也没有记载它们。它们在 DOM 上存在，但不承诺稳定，随时可能改名或消失。要靠它们出样式，先在 issue 里提出来。</p><hr><h2 id="四、css-自定义属性与-layer" tabindex="-1">四、CSS 自定义属性与 <code>@layer</code> <a class="header-anchor" href="#四、css-自定义属性与-layer" aria-label="Permalink to &quot;四、CSS 自定义属性与 `@layer`&quot;">​</a></h2><h3 id="受约束-2" tabindex="-1">受约束 <a class="header-anchor" href="#受约束-2" aria-label="Permalink to &quot;受约束&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>说明</th></tr></thead><tbody><tr><td><code>@layer</code> 名与声明顺序</td><td>5</td><td><code>xihan.reset</code> → <code>xihan.tokens</code> → <code>xihan.motion</code> → <code>xihan.components</code> → <code>xihan.overrides</code>。改名、调序、增删中间层全是 major。<code>xihan.overrides</code> 是<strong>故意留空的</strong>，专门给你覆盖用，不会被「清理未使用的层」删掉</td></tr><tr><td>全局令牌 · 原语层</td><td>90</td><td><code>--xh-color-brand-500</code>、<code>--xh-space-4</code>、<code>--xh-radius-md</code>。皮肤里不该直接用它们，但接品牌轴必须写 <code>--xh-color-brand-*</code>，所以它们是公开的</td></tr><tr><td>全局令牌 · 语义层</td><td>83</td><td><code>--xh-bg-brand</code>、<code>--xh-fg-on-brand</code>、<code>--xh-control-h-md</code>、<code>--xh-shape-control</code>。主题定制的正门，见 <a href="./theme">设计令牌与主题</a></td></tr><tr><td>组件覆盖槽</td><td>1861（覆盖 100 个组件）</td><td><code>--xh-button-bg</code>、<code>--xh-button-h</code>、<code>--xh-dialog-max-w</code>。全部写成 <code>var(--xh-x-y, 默认值)</code> 形态，你在 <code>:root</code> 里设它就改了这个组件</td></tr><tr><td>语气轴槽</td><td>11</td><td><code>--xh-_tone</code>、<code>--xh-_tone-on</code>、<code>--xh-_tone-hover</code>、<code>--xh-_tone-subtle</code>、<code>--xh-_tone-border</code> 等。<strong>这是自定义语气的唯一机制</strong>——你写 <code>[data-tone=&#39;premium&#39;] { --xh-_tone: gold; --xh-_tone-on: #000 }</code>，全库 45 份皮肤都会跟着走。虽然带下划线前缀，但按受约束处理</td></tr><tr><td>跨包内联属性</td><td>2</td><td><code>--xh-_ellipsis-lines</code>、<code>--xh-_float-button-offset</code>。由 headless 写进内联 <code>style</code>，皮肤必须读。<strong>换整套皮肤时不读这两条，<code>ellipsis</code> 不截断、<code>float-button</code> 贴边，且不报任何错</strong></td></tr><tr><td><code>@xihan-ui/styles</code> 的 CSS 子路径</td><td>111</td><td><code>.</code>、<code>./index.css</code>、<code>./index.unlayered.css</code>、<code>./layers.css</code>、<code>./tone.css</code> 与 108 条 <code>./&lt;组件&gt;.css</code></td></tr><tr><td><code>@xihan-ui/tokens</code> 的 CSS 子路径</td><td>2</td><td><code>./tokens.css</code>、<code>./tokens.json</code></td></tr></tbody></table><h3 id="排除-2" tabindex="-1">排除 <a class="header-anchor" href="#排除-2" aria-label="Permalink to &quot;排除&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>为什么安全</th></tr></thead><tbody><tr><td>其余 <code>--xh-_</code> 私有槽</td><td>331</td><td>皮肤内部的回退中转（<code>--xh-_bg</code>、<code>--xh-_bg-hover</code>、<code>--xh-_mention-py</code> 等），变体只改槽位不重写规则全靠它。不要在外面设它们</td></tr><tr><td>令牌的<strong>取值</strong></td><td>—</td><td><code>--xh-color-brand-500</code> 这个名字受约束，它等于哪一串 <code>oklch()</code> 不受约束。调色板会随视觉迭代动，这正是令牌存在的意义</td></tr><tr><td><code>index.unlayered.css</code> 的内部结构</td><td>—</td><td>它是生成的扁平镜像，<strong>不带 <code>@layer</code></strong>。走这个入口就没有 <code>xihan.overrides</code> 这个覆盖槽位，层名承诺不适用</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">命名前缀不能反推归属</p><p><code>--xh-field-py</code> 长得像 <code>field</code> 组件的覆盖槽，实际是全局语义令牌，而且 <code>field.css</code> 自己都不用它。同理 <code>--xh-text-*</code>（全局文本令牌）与 <code>text-field</code> 的 27 条组件槽同前缀，<code>--xh-color-*</code>（原语调色板）与 <code>color-picker</code> 的 62 条组件槽同前缀。判断一条属性属于哪一档，看它在不在上表列的那 173 个全局令牌里，不要按前缀猜。</p></div><hr><h2 id="五、自定义元素与-attribute" tabindex="-1">五、自定义元素与 attribute <a class="header-anchor" href="#五、自定义元素与-attribute" aria-label="Permalink to &quot;五、自定义元素与 attribute&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>档位</th></tr></thead><tbody><tr><td>自定义元素标签 <code>xh-*</code></td><td>103（<code>defineXhElements()</code> 注册 102 + <code>xh-background</code>）</td><td><strong>受约束</strong></td></tr><tr><td>注册函数</td><td>2（<code>defineXhElements</code>、<code>defineXhBackground</code>）</td><td><strong>受约束</strong></td></tr><tr><td>observed attribute</td><td>752 条声明 / 216 个不同名字</td><td><strong>受约束</strong>（具体元素上的具体属性名）</td></tr><tr><td>attribute 名词汇表本身</td><td>216</td><td><strong>只增不减</strong>（新组件复用 <code>size</code> / <code>tone</code> / <code>dir</code> 不算破坏）</td></tr><tr><td><code>CustomEvent</code> 名</td><td>46 个名字 / 115 条「元素 × 事件」</td><td><strong>受约束</strong></td></tr><tr><td>事件传播语义</td><td><code>bubbles: true, composed: true</code>（110 处中 109 处）</td><td><strong>受约束</strong>——把冒泡改掉会让祖先节点上的事件委托静默失效</td></tr><tr><td>事件 <code>detail</code> 形状</td><td>106 个 <code>*Details</code> 类型</td><td><strong>受约束</strong>，等同于 headless 的同名类型</td></tr><tr><td><code>attribute: false</code> 的 JS 字段</td><td>90 条（涉及 39 个字段名）</td><td><strong>受约束</strong>。<code>collection</code>、<code>translations</code>、<code>validate</code>、<code>filter</code> 这类只能用 JS 赋值，HTML 里表达不出来——<strong>不是每个 property 都有对应 attribute</strong></td></tr><tr><td>命令式方法</td><td>22（分布在 5 个元素）</td><td><strong>受约束</strong>，含参数与返回类型</td></tr></tbody></table><p>命令式方法全清单：</p><table tabindex="0"><thead><tr><th>元素</th><th>方法</th></tr></thead><tbody><tr><td><code>xh-form</code></td><td><code>setFieldValue</code> <code>setFieldError</code> <code>clearErrors</code> <code>submit</code> <code>reset</code> <code>getFieldId</code> <code>getFieldValue</code> <code>getFieldError</code></td></tr><tr><td><code>xh-toaster</code></td><td><code>create</code> <code>updateToast</code> <code>dismiss</code> <code>dismissAll</code> <code>getToastsByPlacement</code></td></tr><tr><td><code>xh-file-upload</code></td><td><code>openFilePicker</code> <code>setFiles</code> <code>addFiles</code> <code>deleteFile</code> <code>clearFiles</code></td></tr><tr><td><code>xh-virtualizer</code></td><td>3 个</td></tr><tr><td><code>xh-log</code></td><td><code>scrollToBottom</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">布尔 attribute 是三态的</p><p><code>modal=&quot;false&quot;</code> 表示关，不写表示「交给组件决定」——这与原生 HTML 布尔属性（写了即为真）不同。把三态转换器换回原生语义是<strong>不改名字的语义收窄</strong>，按 major 处理。</p></div><p>几条与包结构有关的事实，也在承诺内：</p><ul><li>元素在 <code>@xihan-ui/web-components/define</code>，不在包主入口。<code>defineXhElements()</code> 是全有全无——调它就注册全部 102 个元素，没有逐个的 <code>defineXhButton()</code>。（补细粒度 define 是 minor；补完之后 <code>defineXhElements</code> 的「全量」语义就成了承诺。）</li><li><code>xh-background</code> 单独在 <code>@xihan-ui/web-components/backgrounds</code>，因为它依赖可选 peer。把它挪进 <code>./define</code> 会强制所有人装 WebGL 引擎，属于破坏性变更。</li><li>元素全部是 <strong>Light DOM</strong>，没有 shadow root，<code>::part()</code> 永远不生效。CEM 里的 <code>cssParts</code> 条目在本包读作 <code>data-xh-part</code>，不是 shadow part。</li></ul><hr><h2 id="六、什么算破坏性变更" tabindex="-1">六、什么算破坏性变更 <a class="header-anchor" href="#六、什么算破坏性变更" aria-label="Permalink to &quot;六、什么算破坏性变更&quot;">​</a></h2><p>正例（= major）与反例（= minor / patch）对照，按介质各举几条。</p><h3 id="js-导出" tabindex="-1">JS 导出 <a class="header-anchor" href="#js-导出" aria-label="Permalink to &quot;JS 导出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td>删掉或改名任一 <code>Xh*</code> 组件（含 <code>XhTreeSelectBranchIndicator</code> 这种冷门部件）</td><td>新增组件、新增部件</td></tr><tr><td><code>connectAccordion</code> 的返回值把 <code>getRootProps</code> 改成 <code>getProps</code></td><td>给 <code>connectAccordion</code> 加一个新的 getter</td></tr><tr><td><code>SelectProps</code> 新增一个<strong>必填</strong>字段，或把可选字段改必填</td><td><code>SelectProps</code> 新增可选字段</td></tr><tr><td><code>SelectApi</code> 删掉一个 getter</td><td><code>SelectContext</code> 加一个可选字段</td></tr><tr><td>把 <code>useSelect()</code> 的返回从 <code>ComputedRef&lt;Api&gt;</code> 换成别的容器</td><td>新增 <code>useXxx</code></td></tr><tr><td>把某个 prop 从裸 <code>Boolean</code> 改成 <code>default: undefined</code></td><td>给某个 prop 补文档</td></tr><tr><td>从某个组件的 <code>emits</code> 数组里删一个名字</td><td>往 <code>emits</code> 里加一个名字</td></tr></tbody></table><h3 id="解剖与-data" tabindex="-1">解剖与 <code>data-*</code> <a class="header-anchor" href="#解剖与-data" aria-label="Permalink to &quot;解剖与 `data-*`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td><code>data-part</code> 从 <code>indicator</code> 改成 <code>marker</code></td><td>给某个组件新增一个可选部件</td></tr><tr><td>把 <code>item-text</code> 改成 <code>itemText</code>（分词/大小写变化）</td><td>皮肤内部改用别的选择器组合实现同样的视觉</td></tr><tr><td>某个组件不再输出 <code>data-size</code> / <code>data-tone</code></td><td>给某个组件补上原本没有的 <code>data-tone</code></td></tr><tr><td><code>data-state</code> 的取值从 <code>open</code> 改成 <code>expanded</code></td><td>新增一个 <code>data-state</code> 取值</td></tr><tr><td>把 <code>data-disabled</code> 从「存在即禁用」改成 <code>data-disabled=&quot;true&quot;</code></td><td>—</td></tr><tr><td>删掉 <code>data-value</code></td><td>删掉 <code>data-lane</code>（在排除清单里）</td></tr></tbody></table><h3 id="css" tabindex="-1">CSS <a class="header-anchor" href="#css" aria-label="Permalink to &quot;CSS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td><code>--xh-button-h</code> 改名成 <code>--xh-button-block-size</code></td><td>新增 <code>--xh-button-letter-spacing</code></td></tr><tr><td>删掉 <code>--xh-radius-xl</code>（哪怕库内部没人用它）</td><td>把 <code>--xh-color-brand-500</code> 的 <code>oklch()</code> 值调深一点</td></tr><tr><td>把 <code>var(--xh-alert-px, …)</code> 改成直接写死语义令牌（等于取消这个覆盖点）</td><td>给某条规则补 <code>@supports</code> 兜底</td></tr><tr><td>调整 <code>@layer</code> 声明顺序</td><td>在 <code>xihan.components</code> 里加规则</td></tr><tr><td>删掉 <code>./tone.css</code> 子路径</td><td>新增 <code>./&lt;新组件&gt;.css</code> 子路径</td></tr></tbody></table><h3 id="自定义元素" tabindex="-1">自定义元素 <a class="header-anchor" href="#自定义元素" aria-label="Permalink to &quot;自定义元素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td><code>xh-empty-state</code> 改名成 <code>xh-empty</code></td><td>新增 <code>xh-xxx</code> 元素</td></tr><tr><td>某元素的 <code>observedAttributes</code> 里少一条</td><td>给某元素新增 attribute</td></tr><tr><td>把 <code>read-only</code> 改写成 <code>readonly</code></td><td>把某个 <code>attribute: false</code> 的字段反向暴露成 attribute</td></tr><tr><td>事件名 <code>value-change</code> 改成 <code>change</code></td><td>新增事件名</td></tr><tr><td>把某个事件的 <code>bubbles</code> 改成 <code>false</code></td><td>补 <code>HTMLElementEventMap</code> 类型增强</td></tr><tr><td><code>xh-toaster.create()</code> 从返回 <code>string</code> 改成返回对象</td><td>给 <code>xh-form</code> 新增一个方法</td></tr><tr><td>把某个可选 part 提升为 <code>requiredParts</code></td><td>新增一个可选 part</td></tr></tbody></table><h3 id="支持面" tabindex="-1">支持面 <a class="header-anchor" href="#支持面" aria-label="Permalink to &quot;支持面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算破坏</th><th>不算破坏</th></tr></thead><tbody><tr><td>抬高 Node 下限</td><td>降低 Node 下限</td></tr><tr><td>抬高浏览器硬底线（用一个无兜底的新 CSS 特性）</td><td>加一个带退化路径的增强特性</td></tr><tr><td>收窄 <code>vue</code> peer 区间（加上限、抬下限）</td><td>放宽 peer 区间</td></tr><tr><td>撤掉 ESM 导出条件</td><td>增加 CJS 导出条件</td></tr></tbody></table><hr><h2 id="七、废弃流程" tabindex="-1">七、废弃流程 <a class="header-anchor" href="#七、废弃流程" aria-label="Permalink to &quot;七、废弃流程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>介质</th><th>怎么被看见</th></tr></thead><tbody><tr><td>JS / TS 导出</td><td>源码标 <code>@deprecated</code>，IDE 划删除线；类型上仍可用</td></tr><tr><td>Vue prop / emit / 插槽</td><td>同上，另在组件文档页标注</td></tr><tr><td><code>data-*</code>、CSS 自定义属性、<code>@layer</code> 名、元素 attribute</td><td>这四种介质<strong>没有 IDE 提示</strong>。废弃只能通过更新日志的「废弃」小节告知，dev 构建下经 <a href="./diagnostics">诊断通道</a> 发 <code>warn</code>（此项尚未落地，见下节）</td></tr></tbody></table><p>保留期：<strong>标记废弃后，至少保留到下一个 major，且不少于两个 minor 版本，取更长者。</strong> 例如在 <code>1.3.0</code> 标废弃，最早也要等到 <code>2.0.0</code> 才能删；如果 <code>2.0.0</code> 紧跟在 <code>1.3.0</code> 之后发布，则顺延到 <code>1.5.0</code> 之后的那个 major。</p><p>废弃期间不改行为，只加提示。删除动作一律出现在 major 的更新日志顶部，单列一节。</p><hr><h2 id="八、支持面" tabindex="-1">八、支持面 <a class="header-anchor" href="#八、支持面" aria-label="Permalink to &quot;八、支持面&quot;">​</a></h2><p>收窄支持面按破坏性变更处理，放宽随时可以。</p><h3 id="运行时" tabindex="-1">运行时 <a class="header-anchor" href="#运行时" aria-label="Permalink to &quot;运行时&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th><th>变更规则</th></tr></thead><tbody><tr><td>Node（安装并运行本库）</td><td><strong>≥ 18</strong></td><td>抬高 = major。产物实际用到的最高特性是 <code>Object.hasOwn</code>（Node 16.9），<code>&gt;=18</code> 留了余量</td></tr><tr><td>Node（开发本仓库）</td><td>≥ 24，pnpm ≥ 11</td><td>与上面是两码事，随时可动</td></tr><tr><td>模块格式</td><td><strong>ESM only</strong></td><td>无 CJS、无 node10 解析条件。包里 <code>main</code> / <code>module</code> 字段存在但指向 ESM 文件，是给老式 bundler 的别名，<strong>不代表可以 <code>require</code></strong></td></tr><tr><td>包管理器</td><td>无要求</td><td>—</td></tr></tbody></table><h3 id="浏览器" tabindex="-1">浏览器 <a class="header-anchor" href="#浏览器" aria-label="Permalink to &quot;浏览器&quot;">​</a></h3><p>硬底线由三个<strong>无兜底</strong>的 CSS 特性决定：<code>@layer</code>（108/108 个样式文件都在用，不认它的解析器会丢弃整块）、<code>oklch()</code>（45 处，是唯一颜色来源）、<code>color-mix()</code>。</p><table tabindex="0"><thead><tr><th>浏览器</th><th>硬底线</th><th>完整保真</th></tr></thead><tbody><tr><td>Chrome / Edge</td><td><strong>111</strong></td><td>111</td></tr><tr><td>Firefox</td><td><strong>113</strong></td><td>121（<code>:has()</code>）</td></tr><tr><td>Safari</td><td><strong>16.2</strong></td><td>16.4</td></tr></tbody></table><p>测试承诺：当前正式版，外加 Chromium 与 Safari 各往前两个大版本、Firefox ESR。硬底线只在 major 里抬高。</p><p>低于硬底线不会降级、会<strong>无样式</strong>——皮肤里刻意不写兜底值，令牌缺席是缺陷而不是降级。</p><p>可选增强层（不支持时按下表退化，加新的增强特性不算破坏，前提是退化路径一起加）：</p><table tabindex="0"><thead><tr><th>特性</th><th>Chrome</th><th>Firefox</th><th>Safari</th><th>不支持时</th></tr></thead><tbody><tr><td><code>:has()</code></td><td>105</td><td>121</td><td>15.4</td><td>少量间距/gutter 微调失效</td></tr><tr><td><code>scrollbar-gutter</code></td><td>94</td><td>97</td><td>18.2</td><td>滚动条出现时轻微位移</td></tr><tr><td><code>dvh</code> / <code>svh</code> / <code>lvh</code></td><td>108</td><td>101</td><td>15.4</td><td>回落到 <code>vh</code></td></tr><tr><td><code>text-wrap: balance</code></td><td>114</td><td>121</td><td>17.5</td><td>标题按默认换行</td></tr><tr><td><code>light-dark()</code></td><td>123</td><td>120</td><td>17.5</td><td>代码块语法色退化成单色</td></tr><tr><td><code>field-sizing</code></td><td>123</td><td>152</td><td>26.2</td><td><code>composer</code> 输入框退化成固定行数</td></tr></tbody></table><p>Web Components 侧不构成额外约束：全部 Light DOM，不用 shadow DOM、<code>ElementInternals</code>、<code>adoptedStyleSheets</code>，平台要求只到 Custom Elements v1。</p><h3 id="宿主框架" tabindex="-1">宿主框架 <a class="header-anchor" href="#宿主框架" aria-label="Permalink to &quot;宿主框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包</th><th>peer</th><th>规则</th></tr></thead><tbody><tr><td><code>@xihan-ui/vue</code></td><td><code>vue: ^3.5.0</code></td><td>下限由 <code>useId</code> 决定（Vue 3.5 引入）。<strong>收窄 = major，放宽 = minor</strong></td></tr><tr><td><code>@xihan-ui/vue</code>、<code>@xihan-ui/web-components</code></td><td><code>@xihan-ui/backgrounds</code>（optional）</td><td>不用背景效果就不必装</td></tr><tr><td><code>@xihan-ui/web-components</code></td><td>无</td><td>原生自定义元素，不要求任何框架</td></tr><tr><td>其余 11 个包</td><td>无</td><td>—</td></tr></tbody></table><hr><h2 id="九、包的稳定性分级" tabindex="-1">九、包的稳定性分级 <a class="header-anchor" href="#九、包的稳定性分级" aria-label="Permalink to &quot;九、包的稳定性分级&quot;">​</a></h2><p>锁步发版意味着版本号看不出稳定性，所以单列一张表。</p><h3 id="稳定" tabindex="-1">稳定 <a class="header-anchor" href="#稳定" aria-label="Permalink to &quot;稳定&quot;">​</a></h3><p>破坏性变更只出现在 major，废弃走上面的流程。</p><table tabindex="0"><thead><tr><th>包</th><th>说明</th></tr></thead><tbody><tr><td><code>@xihan-ui/vue</code></td><td>568 个组件、72 个组合式函数</td></tr><tr><td><code>@xihan-ui/web-components</code></td><td>103 个自定义元素</td></tr><tr><td><code>@xihan-ui/headless</code></td><td><code>connect*</code> / <code>*Machine</code> / 各类公开类型；内部算子在排除清单里</td></tr><tr><td><code>@xihan-ui/styles</code></td><td>108 份皮肤、5 个层名</td></tr><tr><td><code>@xihan-ui/tokens</code></td><td>173 个令牌名</td></tr><tr><td><code>@xihan-ui/icons</code></td><td>图标集</td></tr><tr><td><code>@xihan-ui/kernel</code></td><td>只有被适配器与 headless 公开消费的那部分（<code>createAnatomy</code>、<code>createNormalizer</code>、归一化规则）</td></tr><tr><td><code>@xihan-ui/machine</code></td><td>同上</td></tr><tr><td><code>@xihan-ui/behavior</code></td><td>同上，含 <code>data-value</code> 这条集合导航契约</td></tr><tr><td><code>@xihan-ui/position</code></td><td><code>createPositionEngine</code> 与它的选项；其余 9 个导出是内部算子</td></tr></tbody></table><h3 id="实验" tabindex="-1">实验 <a class="header-anchor" href="#实验" aria-label="Permalink to &quot;实验&quot;">​</a></h3><p><strong>这四个包的破坏性变更可以出现在 minor 里。</strong> 不适合放进不易升级的生产代码。</p><table tabindex="0"><thead><tr><th>包</th><th>为什么还在动</th></tr></thead><tbody><tr><td><code>@xihan-ui/code-highlight</code></td><td>承诺面是 <code>HighlighterPort</code> 这个端口，自研分词器（<code>tokenizeCode</code>、<code>langSpecOf</code>、<code>LangSpec</code>）随时可能整体换掉</td></tr><tr><td><code>@xihan-ui/markdown</code></td><td>公开面只有 <code>createStreamRenderer</code> 与它的三个类型；解析、切块、缓存的中间件随时会变</td></tr><tr><td><code>@xihan-ui/chat-stream</code></td><td>AI 会话协议类型（<code>UIMessage</code>、<code>TextPart</code> 等）跟随上游生态演进</td></tr><tr><td><code>@xihan-ui/backgrounds</code></td><td>效果参数与点云 API 仍在调整；通用短名（<code>bool</code> / <code>num</code> / <code>str</code> / <code>rgb</code>）不是公开 API</td></tr></tbody></table><hr><h2 id="门禁兜住了什么" tabindex="-1">门禁兜住了什么 <a class="header-anchor" href="#门禁兜住了什么" aria-label="Permalink to &quot;门禁兜住了什么&quot;">​</a></h2><h3 id="已经焊死的" tabindex="-1">已经焊死的 <a class="header-anchor" href="#已经焊死的" aria-label="Permalink to &quot;已经焊死的&quot;">​</a></h3><p><strong>六种介质的「改名 = major」现在有门禁兜着。</strong> <code>pnpm gate</code> 里的 <code>check-public-surface</code> 拿一份入库的基线（<code>ui/tooling/public-surface.json</code>，6665 个名字）比对当前状态： <strong>基线里有而当前没有，就是删了或改名了，构建失败</strong>。新增一律放行，因为那是 minor。</p><p>覆盖：包名与 133 条子入口、3017 个导出名、102 个 <code>data-scope</code> 与 569 条部件配对、 102 个组件的 936 个 prop 名、114 种 <code>data-*</code>、22 个 <code>data-state</code> 取值、173 个令牌、 5 个 <code>@layer</code> 名、1856 个组件覆盖槽、102 个自定义元素及其 attribute 与事件。</p><p>prop 名那一维是后补的：在它进来之前，改一个 prop 名（实测 <code>transfer</code> 的 <code>items</code> 改 <code>collection</code>、<code>splitter</code> 的 <code>size</code> 改 <code>sizes</code>）13 道门禁全程沉默。它的事实源是无头内核的 <code>&lt;组件&gt;Schema[&#39;props&#39;]</code>，两个适配器的 props 都照它铺。</p><p>它存在的理由可以复现：把 <code>switch</code> 的 <code>thumb</code> 改名 <code>knob</code>，其余 12 道门禁全部通过， 只有这一道拦下来；把 <code>switch</code> 的 <code>checked</code> 改名 <code>isChecked</code>，同样只有它报出 「组件 prop switch: checked」。删一个语义令牌、改一个组件覆盖槽名同理。</p><p>真要做破坏性变更时，跑 <code>pnpm surface:update</code> 推基线并在 changeset 里说清—— 门禁拦的是「无意中删掉」，不是「有意的 major」。</p><p><strong>三条视觉轴已收成联合类型</strong>，<code>tone</code> / <code>size</code> / <code>variant</code> 不再是裸 <code>string</code>， 写错值编译期就报错。<strong>Vue 事件载荷也有类型了</strong>，69 个组件的 <code>emits</code> 改成对象式， 产物里 <code>(...args: any[]) =&gt; any</code> 从 188 处降到 0。</p><h3 id="仍然只靠自觉的" tabindex="-1">仍然只靠自觉的 <a class="header-anchor" href="#仍然只靠自觉的" aria-label="Permalink to &quot;仍然只靠自觉的&quot;">​</a></h3><p>下面这些<strong>目前没有门禁</strong>。列在这里，比假装什么都兜得住有用。</p><table tabindex="0"><thead><tr><th>条款</th><th>现状</th><th>计划补的机制</th></tr></thead><tbody><tr><td>Vue 作用域插槽载荷</td><td>没有一个组件声明 <code>slots:</code> 选项，<code>&lt;template #default=&quot;s&quot;&gt;</code> 里的 <code>s</code> 是隐式 <code>any</code></td><td>补 <code>slots:</code> 声明</td></tr><tr><td>废弃提示（CSS / <code>data-*</code> / attribute / 层名）</td><td>这四种介质没有任何提示机制，废弃只能靠更新日志</td><td>dev 构建下经诊断通道发 <code>warn</code></td></tr><tr><td>浏览器硬底线</td><td>仓库里没有 <code>browserslist</code>，也没有 CSS 特性白名单。写一个 <code>@container</code> 就能把底线从 2023-03 抬到 2023-09，没有一条门禁会响</td><td><code>.browserslistrc</code> + 无兜底新特性的拒绝名单</td></tr><tr><td>「14 个包必须同版本」</td><td>兄弟包是普通 <code>dependencies</code> 而非 <code>peerDependencies</code>，包管理器不会阻止你装出混版组合</td><td>提成 peer，或在入口加运行期版本一致性检查</td></tr></tbody></table><p>发现本页写的和实际行为对不上，按缺陷处理——请提 issue，不要当成「政策就是这样」。</p>',117)])])}const b=d(a,[["render",r]]);export{u as __pageData,b as default};
